/* The tables of M33 · Shop and canteen. */

export const shopOutlets = defineTable(
  'shop_outlets',
  { module: 'M33', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** "Uniform shop", "Canteen" */
    name: text().notNull(),
    kind: enumText(shopOutletKinds).notNull(),
    /** where its stock is held */
    warehouseId: uuid()
      .references((): AnyPgColumn => warehouses.id)
      .notNull(),
    acceptsCash: boolean().notNull().default(true),
    acceptsWallet: boolean().notNull().default(true),
    /** a sale may be added to the family's next fee voucher */
    allowsChargeToFees: boolean().notNull().default(false),
    receiptNote: text(),
    isActive: boolean().notNull().default(true),
  },
  (t) => [uniqueIndex('shop_outlets_branch_name_uq').on(t.branchId, t.name).where(live(t))],
);

/** What is offered for sale and at what price. */
export const shopProducts = defineTable(
  'shop_products',
  { module: 'M33', scope: 'org', member: { read: { isActive: true } } },
  {
    ...baseColumns,
    name: text().notNull(),
    nameUr: text(),
    outletKind: enumText(shopProductOutletKinds).notNull(),
    /** set when it is a stocked item; empty for food made to order */
    itemId: uuid().references((): AnyPgColumn => inventoryItems.id),
    /** `{ itemId, quantity }[]` for a set, such as "Grade 5 book set" */
    bundle: jsonb().notNull().default([]),
    /** a tile group on the sale screen */
    category: text(),
    /** tax included */
    price: paisa().notNull(),
    /** for book sets and uniforms by grade */
    gradeIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    /** guardians may block it for their child */
    isRestrictable: boolean().notNull().default(false),
    imageFileId: uuid().references((): AnyPgColumn => files.id),
    sortOrder: integer().notNull().default(0),
    isActive: boolean().notNull().default(true),
  },
  (t) => [nonNegative('shop_products', t.price)],
);

/** A shift at a till. */
export const shopSessions = defineTable(
  'shop_sessions',
  { module: 'M33', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    outletId: uuid()
      .references((): AnyPgColumn => shopOutlets.id)
      .notNull(),
    cashierId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    openedAt: timestamptz().notNull(),
    openingFloat: paisa().notNull().default(0),
    closedAt: timestamptz(),
    expectedCash: paisa(),
    countedCash: paisa(),
    difference: paisa(),
    /** required when not zero */
    differenceNote: text(),
    status: enumText(shopSessionStatuses).notNull().default('open'),
    deviceId: uuid().references((): AnyPgColumn => syncDevices.id),
  },
  (t) => [
    nonNegative('shop_sessions', t.openingFloat),
    nonNegative('shop_sessions', t.expectedCash),
    nonNegative('shop_sessions', t.countedCash),
    check(
      'shop_sessions_difference_note_needed',
      sql`coalesce(${t.difference}, 0) = 0 or ${t.differenceNote} is not null`,
    ),
    uniqueIndex('shop_sessions_open_uq')
      .on(t.cashierId, t.outletId)
      .where(sql`${t.status} = 'open' and ${t.deletedAt} is null`),
  ],
);

export const shopSales = defineTable(
  'shop_sales',
  { module: 'M33', scope: 'branch', family: 'studentId' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `shop_sale` sequence */
    saleNo: text().notNull(),
    /** printed on a receipt made offline */
    deviceReceiptCode: text(),
    outletId: uuid()
      .references((): AnyPgColumn => shopOutlets.id)
      .notNull(),
    sessionId: uuid()
      .references((): AnyPgColumn => shopSessions.id)
      .notNull(),
    soldAt: timestamptz().notNull(),
    /** required for wallet and charge-to-fees */
    studentId: uuid().references((): AnyPgColumn => students.id),
    familyId: uuid().references((): AnyPgColumn => families.id),
    /** a sale to a staff member */
    staffId: uuid().references((): AnyPgColumn => staff.id),
    /** the sum of its lines */
    total: paisa().notNull(),
    paidCash: paisa().notNull().default(0),
    paidWallet: paisa().notNull().default(0),
    /** the three add up to `total` */
    chargedToFees: paisa().notNull().default(0),
    status: enumText(shopSaleStatuses).notNull().default('completed'),
    voidReason: text(),
    soldBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [
    check(
      'shop_sales_student_id_needed',
      sql`(${t.paidWallet} = 0 and ${t.chargedToFees} = 0) or ${t.studentId} is not null`,
    ),
    nonNegative('shop_sales', t.total),
    nonNegative('shop_sales', t.paidCash),
    nonNegative('shop_sales', t.paidWallet),
    nonNegative('shop_sales', t.chargedToFees),
    uniqueIndex('shop_sales_sale_no_uq').on(t.orgId, t.saleNo).where(live(t)),
    uniqueIndex('shop_sales_device_receipt_code_uq')
      .on(t.orgId, t.deviceReceiptCode)
      .where(live(t)),
    index('shop_sales_student_sold_at_idx').on(t.orgId, t.studentId, t.soldAt),
    index('shop_sales_session_idx').on(t.orgId, t.sessionId),
  ],
);

export const shopSaleLines = defineTable(
  'shop_sale_lines',
  { module: 'M33', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    saleId: uuid()
      .references((): AnyPgColumn => shopSales.id)
      .notNull(),
    productId: uuid()
      .references((): AnyPgColumn => shopProducts.id)
      .notNull(),
    /** copied */
    name: text().notNull(),
    quantity: decimal(10, 3).notNull(),
    unitPrice: paisa().notNull(),
    discount: paisa().notNull().default(0),
    total: paisa().notNull(),
    /** the average cost at the sale, for cost of sales */
    cost: paisa().notNull().default(0),
    returnedQuantity: decimal(10, 3).notNull().default(0),
  },
  (t) => [
    positive('shop_sale_lines', t.quantity),
    nonNegative('shop_sale_lines', t.unitPrice),
    nonNegative('shop_sale_lines', t.discount),
    nonNegative('shop_sale_lines', t.total),
    nonNegative('shop_sale_lines', t.cost),
    check('shop_sale_lines_returned_quantity_upto', sql`${t.returnedQuantity} <= ${t.quantity}`),
  ],
);

export const shopReturns = defineTable(
  'shop_returns',
  { module: 'M33', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `shop_return` sequence */
    returnNo: text().notNull(),
    saleId: uuid()
      .references((): AnyPgColumn => shopSales.id)
      .notNull(),
    sessionId: uuid()
      .references((): AnyPgColumn => shopSessions.id)
      .notNull(),
    /** `{ saleLineId, quantity, restock }[]` */
    lines: jsonb().notNull(),
    amount: paisa().notNull(),
    /** follows how the sale was paid */
    refundTo: enumText(shopReturnRefundToOptions).notNull(),
    reason: text().notNull(),
    processedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [nonNegative('shop_returns', t.amount)],
);

/** One per student, created on first use. */
export const studentWallets = defineTable(
  'student_wallets',
  { module: 'M33', scope: 'org', family: 'studentId' },
  {
    ...baseColumns,
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    balance: paisa().notNull().default(0),
    /** the most that can be spent in a day */
    dailyLimit: paisa(),
    lowBalanceAlert: paisa(),
    blockedProductIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    nonNegative('student_wallets', t.balance),
    nonNegative('student_wallets', t.dailyLimit),
    nonNegative('student_wallets', t.lowBalanceAlert),
    uniqueIndex('student_wallets_student_uq').on(t.studentId).where(live(t)),
  ],
);

export const walletTransactions = defineTable(
  'wallet_transactions',
  { module: 'M33', scope: 'org', family: 'studentId', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    walletId: uuid()
      .references((): AnyPgColumn => studentWallets.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    kind: enumText(walletTransactionKinds).notNull(),
    /** signed: money in is positive */
    amount: paisa().notNull(),
    balanceAfter: paisa().notNull(),
    saleId: uuid().references((): AnyPgColumn => shopSales.id),
    /** `counter`, `online`, `shop_sale`, `shop_return`, `manual`, `leaving` */
    sourceType: text().notNull(),
    sourceId: uuid(),
    note: text(),
    doneBy: uuid().references((): AnyPgColumn => profiles.id),
  },
  (t) => [
    nonNegative('wallet_transactions', t.balanceAfter),
    uniqueIndex('wallet_transactions_source_type_source_kind_uq')
      .on(t.sourceType, t.sourceId, t.kind)
      .where(sql`${t.sourceId} is not null`),
    index('wallet_transactions_wallet_created_at_idx').on(t.orgId, t.walletId, t.createdAt),
  ],
);

export const canteenMenus = defineTable(
  'canteen_menus',
  { module: 'M33', scope: 'branch', member: { read: { status: 'published' } } },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    weekStart: dateStr().notNull(),
    /** `{ weekday, productIds[] , note? }[]` */
    days: jsonb().notNull(),
    status: enumText(canteenMenusStatuses).notNull().default('draft'),
  },
  (t) => [
    check('canteen_menus_week_start_monday', sql`extract(isodow from ${t.weekStart}) = 1`),
    uniqueIndex('canteen_menus_branch_week_start_uq').on(t.branchId, t.weekStart).where(live(t)),
  ],
);
